"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[4059],{4059:e=>{e.exports=JSON.parse('{"concept":"Time Zone Calculations","subject":"mathematics","category":"Applied Problem Solving","explanation":"Time zone problems combine time arithmetic with logical reasoning. Key principles: Earth has 24 time zones, each 1 hour apart. Moving east = add hours, moving west = subtract hours. Account for crossing midnight (day changes). Flight duration stays the same regardless of time zones - only arrival/departure times change based on local time.","examples":[{"question":"A flight leaves London at 14:30 and takes 8 hours. If London is 5 hours ahead of New York, what time does it arrive in New York (local time)?","solution":"17:30 New York time","explanation":"Arrival in London time: 14:30 + 8 hours = 22:30. Convert to New York time: 22:30 - 5 hours = 17:30."},{"question":"It\'s 09:00 Monday in Tokyo. What time and day is it in Los Angeles if Tokyo is 17 hours ahead?","solution":"16:00 Sunday in Los Angeles","explanation":"Los Angeles time = Tokyo time - 17 hours. 09:00 Monday - 17 hours = 09:00 - 17:00 = -8:00. This means 16:00 the previous day (Sunday)."},{"question":"A conference call is scheduled for 15:00 in Dubai. If Dubai is 4 hours ahead of London and 9 hours ahead of New York, what time should people join from each city?","solution":"London: 11:00, New York: 06:00","explanation":"London: 15:00 - 4 hours = 11:00. New York: 15:00 - 9 hours = 06:00."}],"exercises":[{"type":"multiple-choice","question":"A flight leaves Sydney at 22:00 Friday and takes 14 hours. If Sydney is 11 hours ahead of London, what time does it arrive in London?","options":["01:00 Saturday","12:00 Saturday","01:00 Sunday","25:00 Friday"],"correct":[0],"explanation":"Arrival Sydney time: 22:00 + 14 hours = 12:00 Saturday. London time: 12:00 - 11 hours = 01:00 Saturday."},{"type":"multiple-choice","question":"If it\'s 18:00 Wednesday in Berlin and Berlin is 6 hours ahead of New York, what time is it in New York?","options":["12:00 Wednesday","24:00 Wednesday","00:00 Thursday","12:00 Thursday"],"correct":[0],"explanation":"New York time = Berlin time - 6 hours = 18:00 - 6 hours = 12:00 Wednesday."},{"type":"open-ended","question":"Sarah lives in Mumbai (GMT+5:30) and wants to call her friend in San Francisco (GMT-8) at 10:00 San Francisco time. What time should Sarah make the call?","sample_answer":"Mumbai is 13.5 hours ahead of San Francisco (5:30 - (-8) = 13:30). So 10:00 San Francisco time = 10:00 + 13:30 = 23:30 (11:30 PM) Mumbai time.","explanation":"Calculate the time difference, then add it to the target time in the western city."}],"tips":["Draw a timeline to visualize the problem","Always specify AM/PM and date when crossing midnight","East = add hours, West = subtract hours","Flight duration doesn\'t change - only local times do","Be careful with date changes when crossing midnight"]}')}}]);